param(\n    [int]$MaxPages = 100,\n    [int]$MaxItems = 100\n)\n\n$ErrorActionPreference = "Stop"\n$RepoRoot = (Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path\n$Python = Join-Path $RepoRoot ".venv\Scripts\python.exe"\n$Script = Join-Path $RepoRoot "scripts\run_autofill_cycle.py"\n$LogDir = Join-Path $RepoRoot "logs"\n$LogFile = Join-Path $LogDir "autofill-cycle.log"\n\nif (-not (Test-Path $Python)) { throw "Python virtual environment not found: $Python" }\nif (-not (Test-Path $Script)) { throw "Autofill script not found: $Script" }\n\nNew-Item -ItemType Directory -Path $LogDir -Force | Out-Null\nPush-Location $RepoRoot\ntry {\n    $stamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"\n    "[$stamp] START autofill cycle" | Out-File -FilePath $LogFile -Append -Encoding utf8\n    & $Python $Script --max-pages $MaxPages --max-items $MaxItems 2>&1 | Tee-Object -FilePath $LogFile -Append\n    $exitCode = $LASTEXITCODE\n    $stamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"\n    "[$stamp] END autofill cycle exit=$exitCode" | Out-File -FilePath $LogFile -Append -Encoding utf8\n    exit $exitCode\n}\nfinally {\n    Pop-Location\n}\n